class Solution {
public:
    int countOfArrays(int n, int m, int k) {
        const int MOD = 1000000007;
        long long evenChoices = m / 2, oddChoices = m - evenChoices;
        vector<array<long long, 2>> dp(k + 1), next(k + 1);
        dp[0] = {oddChoices, evenChoices};
        for (int i = 1; i < n; ++i) {
            fill(next.begin(), next.end(), array<long long, 2>{0, 0});
            for (int j = 0; j <= k; ++j) {
                next[j][0] = ((dp[j][0] + dp[j][1]) * oddChoices) % MOD;
                next[j][1] = dp[j][0] * evenChoices % MOD;
                if (j > 0) next[j][1] = (next[j][1] + dp[j - 1][1] * evenChoices) % MOD;
            }
            dp.swap(next);
        }
        return static_cast<int>((dp[k][0] + dp[k][1]) % MOD);
    }
};
